//@ts-nocheck
import { hierarchy, partition } from "d3-hierarchy";
import { select } from "d3-selection";
import { arc } from "d3-shape";
import merge from "deepmerge";
import {
	preloadSanitizeHtml,
	sanitizeHtml,
	sanitizeHtmlSync,
} from "../../utils/sanitizeHtml";

import {
	computeArcEndAngle,
	computeArcInnerRadius,
	computeArcOutterRadius,
	computeArcStartAngle,
	computeNodeRotation,
	iteratorToAlphabet,
} from "./helper";

const POPOVER_DISTANCE = 10;
const POPOVER_PLACEMENT = "top";
const POPOVER_STYLE_APPLY_DELAY = 10;
const CENTER_TEXT_FACTOR = 3.5;
const LINE_START_PERCENT = 1;
const LINE_END_PERCENT = 1;
const LEAF_EXPAND_FACTOR = 1.1;
const LEAF_EXPAND_DELTA_X = 180;
const LEAF_EXPAND_DELTA_Y = 0;

const addStylesToTree = (obj, walker, config) => {
	if (obj.children) {
		if (obj.depth === 0) {
			obj.children = obj.children.map((r, i) => addStylesToTree(r, i, config));
		} else {
			obj.children = obj.children.map((r) =>
				addStylesToTree(r, walker, config),
			);
		}
	}

	obj.data = {
		...obj.data,
		backgroundColor:
			obj.data.backgroundColor ||
			(obj.depth === 0
				? "var(--info-bg-medium-default)"
				: `var(--accent-${iteratorToAlphabet(walker)}-default)`),
		leaf: {
			...obj.data.leaf,
			label: {
				paddingX:
					obj.data.leaf?.label?.paddingX || config.leaf?.label?.paddingX,
				paddingY:
					obj.data.leaf?.label?.paddingY || config.leaf?.label?.paddingY,
				borderRadius:
					obj.data.leaf?.label?.borderRadius ||
					config.leaf?.label?.borderRadius,
				backgroundColor:
					obj.data.leaf?.label?.backgroundColor ||
					config.leaf?.label?.backgroundColor,
				fontSize:
					obj.data.leaf?.label?.fontSize || config.leaf?.label?.fontSize,
				lineHeight:
					obj.data.leaf?.label?.lineHeight || config.leaf?.label?.lineHeight,
				deltaX: obj.data.leaf?.label?.deltaX || config.leaf?.label?.deltaX,
				deltaY: obj.data.leaf?.label?.deltaY || config.leaf?.label?.deltaY,
			},
			line: {
				color: obj.data.leaf?.line?.color || config.leaf?.line?.color,
				startPercent:
					obj.data.leaf?.line?.startPercent || config.leaf?.line?.startPercent,
				endPercent:
					obj.data.leaf?.line?.endPercent || config.leaf?.line?.endPercent,
			},
			dot: {
				size: obj.data.leaf?.dot?.size || config.leaf?.dot?.size,
				color: obj.data.leaf?.dot?.color || config.leaf?.dot?.color,
				strokeColor:
					obj.data.leaf?.dot?.strokeColor || config.leaf?.dot?.strokeColor,
				strokeWidth:
					obj.data.leaf?.dot?.strokeWidth || config.leaf?.dot?.strokeWidth,
			},
		},
	};
	obj.data.children = undefined;
	return obj;
};

export const renderExploreChart = async ({ chartRef, tooltipRef, config }) => {
	await preloadSanitizeHtml();

	const chartConfig = merge(
		{
			data: {
				name: "Empty Root",
			},
			width: 720,
			height: 480,
			scale: 0.85,
			sector: {
				heightDiff: 0,
				fontSize: 18,
				textUpperDelta1: 32,
				textLowerDelta1: -18,
				textUpperDelta2: 32,
				textLowerDelta2: -18,
				textUpperDelta3: 32,
				textLowerDelta3: -18,
			},
			leaf: {
				label: {
					paddingX: 20,
					paddingY: 10,
					borderRadius: 10,
					backgroundColor: "transparent",
				},
			},
		},
		config,
	);

	if (chartRef.innerHTML.length) {
		chartRef.innerHTML = "";
	}

	const width = chartConfig.width;
	const height = chartConfig.height;
	const radius = Math.min(width, height) / 2;
	let maxDepth = 0;

	const svg = select(chartRef)
		.append("svg")
		.attr("width", width)
		.attr("height", height)
		.append("g")
		.attr(
			"transform",
			`translate(${width / 2},${height / 2}) rotate(-90 0 0) scale(${
				chartConfig.scale
			})`,
		);

	const layout = partition().size([360, radius]).padding(0);
	const root = hierarchy(config.data, (d) => d.children).sum((d) =>
		d.children ? 0 : 1,
	);

	let chartPartition = layout(root);
	chartPartition = addStylesToTree(chartPartition, 0, chartConfig);

	const leaves = chartPartition.leaves();
	const branch = chartPartition.descendants().filter((r) => r.children);

	leaves.forEach((d) => {
		if (d.depth > maxDepth) {
			maxDepth = d.depth;
		}
	});

	const centerArc = arc()
		.startAngle((d) => computeArcStartAngle(d))
		.endAngle((d) => computeArcEndAngle(d))
		.innerRadius((d) => computeArcInnerRadius(d, radius))
		.outerRadius((d) => {
			if (d.depth === maxDepth - 1) {
				return (
					computeArcOutterRadius(d, radius) - chartConfig.sector.heightDiff
				);
			}
			return computeArcOutterRadius(d, radius);
		});

	const polylineContainer = svg.append("g");

	svg
		.selectAll("path")
		.data(branch)
		.enter()
		.append("path")
		.attr("d", centerArc)
		.attr("fill-rule", "evenodd")
		.style("stroke", (d) => d.data.strokeColor || "var(--base-bg-weak-default)")
		.style("fill", (d) => d.data.backgroundColor);

	const g = svg
		.selectAll("g")
		.filter((group) => group === polylineContainer)
		.data(branch)
		.enter()
		.append("g")
		.each(function (d) {
			if (d.depth === 0) {
				select(this).attr("transform", "rotate(90 0 0)");
			}
		});

	g.append("path")
		.attr("d", centerArc)
		.style("fill", "none")
		.each(function (z) {
			const firstArcSection = /(^.+?)L/;
			let pathToFind: string = firstArcSection.exec(
				select(this).attr("d"),
			) as unknown as string;

			if (pathToFind?.[1]) {
				pathToFind = pathToFind[1];
				pathToFind = pathToFind.replace(/,/g, " ");
				const start = computeArcStartAngle(z);
				const end = computeArcEndAngle(z);
				const mid = Math.abs((end - start) / 2 + start);

				if ((mid * 180) / Math.PI >= 180) {
					const startLoc = /M(.*?)A/;
					const middleLoc = /A(.*?)0 0 1/;
					const endLoc = / 0 0 1 (.*?)$/;
					let newStart = endLoc.exec(pathToFind);
					const newEnd = startLoc.exec(pathToFind);
					let middleSec = middleLoc.exec(pathToFind);

					if (!newStart) {
						newStart = / 0 1 1 (.*?)$/.exec(pathToFind);
						middleSec = /A(.*?)0 1 1/.exec(pathToFind);
						if (newStart && middleSec && newEnd) {
							pathToFind = `M${newStart[1]}A${middleSec[1]}0 1 0 ${newEnd[1]}`;
						} else {
							pathToFind = "";
						}
					} else {
						pathToFind = `M${newStart[1]}A${middleSec[1]}0 0 0 ${newEnd[1]}`;
					}
				}

				if (pathToFind.length) {
					select(this)
						.append("path")
						.attr("id", (d) => `harbor-explore-inner-path-id-${d.data.name}`)
						.attr("d", pathToFind)
						.style("fill", "none");
				}
			}
		});

	g.each(function (d) {
		if (d.depth === 0) {
			const fo = select(this)
				.append("foreignObject")
				.attr("x", -computeArcOutterRadius(d, radius))
				.attr("y", -computeArcOutterRadius(d, radius))
				.attr("width", (d) => 2 * computeArcOutterRadius(d, radius))
				.attr("height", (d) => 2 * computeArcOutterRadius(d, radius));

			fo.append("xhtml:div")
				.style(
					"width",
					chartConfig.midSector?.width
						? `${chartConfig.midSector?.width}px`
						: "calc(100% - 1em)",
				)
				.style(
					"height",
					chartConfig.midSector?.height
						? `${chartConfig.midSector?.width}px`
						: "calc(100% - 1em)",
				)
				.style("display", "flex")
				.style("justify-content", "center")
				.style("align-items", "center")
				.style("text-align", "center")
				.style(
					"padding",
					chartConfig.midSector?.padding
						? `${chartConfig.midSector?.padding}px`
						: "0.5em",
				)
				.style(
					"font-size",
					chartConfig.midSector?.fontSize
						? `${chartConfig.midSector?.fontSize}px`
						: `${
								computeArcOutterRadius(d, radius) /
								d.data.name.length /
								CENTER_TEXT_FACTOR
						  }em`,
				)
				.text(d.data.name);
		} else {
			select(this)
				.append("text")
				.attr("dy", (d) => {
					const start = computeArcStartAngle(d);
					const end = computeArcEndAngle(d);
					const mid = Math.abs((end - start) / 2 + start);
					return (mid * 180) / Math.PI >= 180
						? `${chartConfig.sector[`textLowerDelta${d.depth}`]}px`
						: `${chartConfig.sector[`textUpperDelta${d.depth}`]}px`;
				})
				.attr("font-size", () => `${chartConfig.sector.fontSize}px`)
				.attr(
					"font-family",
					'CiscoSans,Arial,Helvetica,"Helvetica Neue",HelveticaNeue,"Lucida Grande",sans-serif',
				)
				.append("textPath")
				.attr("xlink:href", (d) =>
					d.depth === 0 ? "" : `#harbor-explore-inner-path-id-${d.data.name}`,
				)
				.style("text-anchor", "middle")
				.attr("startOffset", "50%")
				.attr("fill", (d) => d.labelColor || "var(--info-bg-medium-active)")
				.text((d) => d.data.name);
		}
	});

	const dotContainer = svg.append("g");
	const dots = dotContainer.selectAll("g").data(leaves).enter();

	const leafArc = arc()
		.startAngle((d) => computeArcStartAngle(d))
		.endAngle((d) => computeArcEndAngle(d))
		.innerRadius((d) => computeArcInnerRadius(d, radius))
		.outerRadius((d) => computeArcOutterRadius(d, radius));

	dots
		.append("circle")
		.attr(
			"cx",
			(d) => computeArcInnerRadius(d, radius) - chartConfig.sector.heightDiff,
		)
		.attr("dy", 0)
		.attr("transform", (d) => `rotate(${computeNodeRotation(d)})`)
		.attr("r", (d) => `${d.data.leaf?.dot?.size || 10}px`)
		.style("fill", (d) => d.data.leaf?.dot?.color || d.data.backgroundColor)
		.style(
			"stroke",
			(d) => d.data.leaf?.dot?.strokeWidth || "var(--base-bg-weak-default)",
		)
		.style("stroke-width", (d) => `${d.data.leaf?.dot?.strokeWidth || 4}px`);

	const labelboxContainer = svg.append("g");

	const bars = labelboxContainer
		.selectAll("allLabels")
		.data(leaves)
		.enter()
		.append("g")
		.attr("transform", (d) => {
			const pos = leafArc.centroid(d);
			const translation = [
				pos[0] * LEAF_EXPAND_FACTOR +
					(d.data.leaf?.label?.deltaY || LEAF_EXPAND_DELTA_Y),
				pos[1] > 0
					? pos[1] + (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X)
					: pos[1] - (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X),
			];

			return `translate(${translation}) rotate(90)`;
		});

	bars
		.append("svg")
		.attr("dx", 0)
		.attr("dy", 0)
		.style("overflow", "visible")
		.append("text")
		.text((d) => d.data.name)
		.attr("fill", "transparent")
		.style("text-anchor", "middle")
		.style("alignment-baseline", "middle")
		.style("pointer-events", "none")
		.attr("font-size", (d) =>
			d.data.leaf.label.fontSize ? `${d.data.leaf.label.fontSize}px` : "100%",
		)
		.each(function (d) {
			const id = `hbr-explore-item-${Math.random().toString(16).slice(2)}`;
			const box = select(this.parentNode).node().getBBox();
			select(this.parentNode)
				.append("foreignObject")
				.attr("id", id)
				.style("color", (d) => d.data.labelColor)
				.attr("x", () => box.x - d.data.leaf.label.paddingX)
				.attr("y", box.y - d.data.leaf.label.paddingY)
				.attr("width", box.width + d.data.leaf.label.paddingX * 2)
				.attr("height", box.height + d.data.leaf.label.paddingY * 2)
				.style("padding", `0 ${d.data.leaf.label.paddingX}px`)
				.style("font-size", `${d.data.leaf.label.fontSize}px`)
				.style(
					"line-height",
					d.data.leaf.label.lineHeight
						? `${d.data.leaf.label.lineHeight}px`
						: "inherit",
				)
				.style("border-radius", `${d.data.leaf.label.borderRadius}px`)
				.style("overflow", "visible")
				.style("cursor", (d) =>
					d.data.event?.click ? "pointer" : "not-allowed",
				)
				.style("user-select", "none")
				.on("mouseenter", (z) => {
					if (d.data.event?.mouseenter) {
						d.data.event.mouseenter(d, z);
					}
				})
				.on("mouseover", async (z) => {
					const { slot, text, containerStyle, placement, distance } =
						d?.data?.tooltip || {};
					if (slot || text) {
						const content = tooltipRef.querySelector(
							"[slot=content]",
						) as HTMLDivElement;
						if (typeof distance === "number") {
							tooltipRef.distance = distance;
						}
						if (placement) {
							tooltipRef.placement = placement;
						}
						if (d?.data?.tooltip) {
							content.innerHTML = await sanitizeHtml(text ?? slot);
						}

						tooltipRef.anchor = `#${id}`;
						if (containerStyle) {
							setTimeout(() => {
								tooltipRef.shadowRoot.querySelector(
									".popover__body",
								).style.cssText = containerStyle;

								if (content.innerHTML.length) {
									tooltipRef.open = true;
								}
							}, POPOVER_STYLE_APPLY_DELAY);
						} else {
							tooltipRef.open = true;
						}
					}
					if (d.data.event?.mouseover) {
						d.data.event.mouseover(d, z);
					}
				})
				.on("mouseout", (z) => {
					if (d?.data?.tooltip?.slot || d?.data?.tooltip?.text) {
						tooltipRef.open = false;
						tooltipRef.querySelector("[slot=content]").innerHTML = "";
						tooltipRef.distance = POPOVER_DISTANCE;
						tooltipRef.placement = POPOVER_PLACEMENT;
						tooltipRef.shadowRoot.querySelector(
							".popover__body",
						).style.cssText = "";
					}
					if (d.data.event?.mouseout) {
						d.data.event.mouseout(d, z);
					}
				})
				.on("click", (z) => {
					if (d.data.event?.click) {
						d.data.event.click(d, z);
					}
				})
				.html((c) => {
					return sanitizeHtmlSync(
						`<div style="display:flex;justify-content:center">${c.data.name}</div>`,
					);
				});

			select(this.parentNode)
				.insert("svg", ":first-child")
				.style("overflow", "visible")
				.style("filter", () => {})
				.append("rect")
				.attr("x", () => box.x - d.data.leaf.label.paddingX)
				.attr("y", box.y - d.data.leaf.label.paddingY)
				.attr("rx", () => d.data.leaf.label.borderRadius)
				.attr("width", () => box.width + d.data.leaf.label.paddingX * 2)
				.attr("height", box.height + d.data.leaf.label.paddingY * 2)
				.style("fill", d.data.leaf.label.backgroundColor)
				.attr("opacity", 1)
				.attr(
					"stroke",
					() => d.data.leaf?.dot?.color || d.data.backgroundColor,
				);
			polylineContainer
				.append("polyline")
				.attr(
					"stroke",
					() =>
						d.data.leaf?.line?.color ||
						d.data.leaf?.dot?.color ||
						d.data.backgroundColor,
				)
				.style("fill", "none")
				.attr("stroke-width", d.data.leaf?.line?.width || 1)
				.attr("points", () => {
					const pos = leafArc.centroid(d);
					const posA = [];
					const posB = [];

					posA[0] =
						(d.data.leaf?.line.startPercent || LINE_START_PERCENT) * pos[0];
					posA[1] =
						(d.data.leaf?.line.startPercent || LINE_START_PERCENT) * pos[1];

					posB[0] = LEAF_EXPAND_FACTOR * pos[0];
					posB[1] = LEAF_EXPAND_FACTOR * pos[1];

					const posC = [
						posB[0] + (d.data.leaf?.label?.deltaY || LEAF_EXPAND_DELTA_Y),
						posB[1] > 0
							? posB[1] +
							  (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X) *
									(d.data.leaf?.line.endPercent || LINE_END_PERCENT)
							: posB[1] -
							  (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X) *
									(d.data.leaf?.line.endPercent || LINE_END_PERCENT),
					];

					return [posA, posB, posC];
				});
		});

	select(self.frameElement).style("height", `${height}px`);
};
