import { scaleLinear, scaleSqrt } from "d3-scale";

const getTransformation = (transform: string) => {
	// Create a dummy g for calculation purposes only. This will never
	// be appended to the DOM and will be discarded once this function
	// returns.
	const g = document.createElementNS("http://www.w3.org/2000/svg", "g");

	// Set the transform attribute to the provided string value.
	g.setAttributeNS(null, "transform", transform);

	// consolidate the SVGTransformList containing all transformations
	// to a single SVGTransform of type SVG_TRANSFORM_MATRIX and get
	// its SVGMatrix.
	const matrix = g.transform.baseVal.consolidate().matrix;

	// Below calculations are taken and adapted from the private function
	// transform/decompose.js of D3's module d3-interpolate.
	let { a, b, c, d, e, f } = matrix; // ES6, if this doesn't work, use below assignment
	// var a=matrix.a, b=matrix.b, c=matrix.c, d=matrix.d, e=matrix.e, f=matrix.f; // ES5
	let scaleX = Math.sqrt(a * a + b * b);
	let scaleY = 0;
	let skewX = 0;
	if (scaleX) {
		a /= scaleX;
		b /= scaleX;
	}

	skewX = a * c + b * d;
	if (skewX) {
		c -= a * skewX;
		d -= b * skewX;
	}

	scaleY = Math.sqrt(c * c + d * d);
	if (scaleY) {
		c /= scaleY;
		d /= scaleY;
		skewX /= scaleY;
	}

	if (a * d < b * c) {
		a = -a;
		b = -b;
		skewX = -skewX;
		scaleX = -scaleX;
	}
	return {
		translateX: e,
		translateY: f,
		rotate: (Math.atan2(b, a) * 180) / Math.PI,
		skewX: (Math.atan(skewX) * 180) / Math.PI,
		scaleX: scaleX,
		scaleY: scaleY,
	};
};
const iteratorToAlphabet = (iterator) => {
	return (iterator + 10).toString(36);
};

const circleLinearScale = () => {
	return scaleLinear()
		.domain([0, 360]) // must be 360 degree
		.range([0, Math.PI * 2])
		.clamp(true);
};

const circleSqrtScale = (containerRadius) => {
	return scaleSqrt()
		.domain([0, 360]) // must be 360 degree
		.range([0, containerRadius])
		.clamp(true);
};

const computeNodeRotation = (d) => {
	const angle = circleLinearScale()(d.x0 + (d.x1 - d.x0) / 2) - Math.PI / 2;
	return (angle / Math.PI) * 180;
};

const computeArcEndAngle = (d) => {
	return Math.max(0, Math.min(2 * Math.PI, circleLinearScale()(d.x1)));
};

const computeArcStartAngle = (d) => {
	return Math.max(0, Math.min(2 * Math.PI, circleLinearScale()(d.x0)));
};

const computeArcInnerRadius = (d, containerRadius) => {
	return Math.max(0, circleSqrtScale(containerRadius)(d.y0));
};

const computeArcOutterRadius = (d, containerRadius) => {
	return Math.max(0, circleSqrtScale(containerRadius)(d.y1));
};

export {
	getTransformation,
	circleLinearScale,
	circleSqrtScale,
	iteratorToAlphabet,
	computeNodeRotation,
	computeArcEndAngle,
	computeArcStartAngle,
	computeArcInnerRadius,
	computeArcOutterRadius,
};
